class QrLogo extends QrDocument {
  /// Its fields; those left out take the core's defaults.
  const QrLogo({
    this.svg,
    this.raster,
    this.size,
    this.scale,
    this.frame,
    this.shape,
    this.padding,
    this.backdrop,
    this.clearModules,
  });

  /// An SVG document; it is sanitized.
  final String? svg;

  /// PNG, JPEG, GIF or WebP bytes.
  final Uint8List? raster;

  final QrLogoSize? size;

  final double? scale;

  final QrLogoFrame? frame;

  final QrLogoShape? shape;

  final double? padding;

  final bool? backdrop;

  final bool? clearModules;

  @override
  Map<String, Object?> toJson() => {
    if (svg != null) 'svg': svg!,
    if (raster != null) 'raster': base64Encode(raster!),
    if (size != null) 'size': size!.json,
    if (scale != null) 'scale': scale!,
    if (frame != null) 'frame': frame!.toJson(),
    if (shape != null) 'shape': shape!.toJson(),
    if (padding != null) 'padding': padding!,
    if (backdrop != null) 'backdrop': backdrop!,
    if (clearModules != null) 'clear_modules': clearModules!,
  };
}

