sealed class QrIntro extends QrDocument {
  const QrIntro();

  const factory QrIntro.preset({
    QrIntroName? preset,
    int? durationMs,
    int? delayMs,
    QrEase? ease,
    QrStagger? stagger,
    int? groups,
    QrTrigger? trigger,
    QrLogoIntro? logo,
    QrLogoTiming? logoTiming,
    QrLogoIntro? frame,
    QrLogoTiming? frameTiming,
  }) = QrIntroPreset;

  /// A palette shift: the code's colors cross-fade from palette_from.
  const factory QrIntro.paletteShift({
    required Map<QrToken, String> paletteFrom,
    int? durationMs,
    QrEase? ease,
    QrTrigger? trigger,
  }) = QrIntroPaletteShift;
}

final class QrIntroPreset extends QrIntro {
  /// Its fields; those left out take the core's defaults.
  const QrIntroPreset({
    this.preset,
    this.durationMs,
    this.delayMs,
    this.ease,
    this.stagger,
    this.groups,
    this.trigger,
    this.logo,
    this.logoTiming,
    this.frame,
    this.frameTiming,
  });

  final QrIntroName? preset;

  final int? durationMs;

  final int? delayMs;

  final QrEase? ease;

  final QrStagger? stagger;

  final int? groups;

  final QrTrigger? trigger;

  final QrLogoIntro? logo;

  final QrLogoTiming? logoTiming;

  final QrLogoIntro? frame;

  final QrLogoTiming? frameTiming;

  @override
  Map<String, Object?> toJson() => {
    if (preset != null) 'preset': preset!.json,
    if (durationMs != null) 'duration_ms': durationMs!,
    if (delayMs != null) 'delay_ms': delayMs!,
    if (ease != null) 'ease': ease!.toJson(),
    if (stagger != null) 'stagger': stagger!.toJson(),
    if (groups != null) 'groups': groups!,
    if (trigger != null) 'trigger': trigger!.toJson(),
    if (logo != null) 'logo': logo!.json,
    if (logoTiming != null) 'logo_timing': logoTiming!.json,
    if (frame != null) 'frame': frame!.json,
    if (frameTiming != null) 'frame_timing': frameTiming!.json,
  };
}

/// A palette shift: the code's colors cross-fade from palette_from.
final class QrIntroPaletteShift extends QrIntro {
  /// Its fields; those left out take the core's defaults.
  const QrIntroPaletteShift({
    required this.paletteFrom,
    this.durationMs,
    this.ease,
    this.trigger,
  });

  final Map<QrToken, String> paletteFrom;

  final int? durationMs;

  final QrEase? ease;

  final QrTrigger? trigger;

  @override
  Map<String, Object?> toJson() => {
    'palette_from': {
      for (final MapEntry(:key, :value) in paletteFrom.entries) key.json: value,
    },
    if (durationMs != null) 'duration_ms': durationMs!,
    if (ease != null) 'ease': ease!.toJson(),
    if (trigger != null) 'trigger': trigger!.toJson(),
  };
}

