/// A Style document (SPEC §10.1). Every key is optional.
class QrStyle extends QrDocument {
  /// A Style document; every part is optional.
  const QrStyle({
    this.preset,
    this.art,
    this.modules,
    this.finders,
    this.alignment,
    this.timing,
    this.palette,
    this.dark,
    this.quietZone,
    this.allowInverted,
    this.frame,
    this.border,
    this.shadow,
    this.colorSpread,
    this.effect,
    this.textures,
    this.caption,
    this.seed,
    this.logo,
    this.halftone,
    this.intro,
    this.idle,
    this.themeTransitionMs,
    this.title,
    this.description,
    this.label,
    this.idPrefix,
    this.targetSize,
    this.minify,
    this.encoding,
  });

  /// The base style: a preset (Style::preset).
  final QrPreset? preset;

  /// The base style: art mode for this picture (Style::art). Not with preset or halftone.
  final QrHalftone? art;

  final QrModuleShape? modules;

  final QrFinders? finders;

  final QrAlignment? alignment;

  final QrTiming? timing;

  /// Token paints, merged onto the base's palette.
  final Map<QrToken, String>? palette;

  /// Render the palette's dark twin and allow inverted colors.
  final bool? dark;

  final int? quietZone;

  final bool? allowInverted;

  final QrFrame? frame;

  final QrBorder? border;

  /// A hard shadow's offset down and right, in modules (0.25–3).
  final double? shadow;

  /// How data modules share fg and the data colors fg.2 to fg.4.
  final QrColorSpread? colorSpread;

  final QrEffect? effect;

  final List<QrTexture>? textures;

  final QrCaption? caption;

  final int? seed;

  final QrLogo? logo;

  final QrHalftone? halftone;

  final QrIntro? intro;

  final List<QrIdle>? idle;

  final int? themeTransitionMs;

  final String? title;

  final String? description;

  final String? label;

  final String? idPrefix;

  final QrTargetSize? targetSize;

  final bool? minify;

  final QrEncoding? encoding;

  @override
  Map<String, Object?> toJson() => {
    if (preset != null) 'preset': preset!.json,
    if (art != null) 'art': art!.toJson(),
    if (modules != null) 'modules': modules!.toJson(),
    if (finders != null) 'finders': finders!.toJson(),
    if (alignment != null) 'alignment': alignment!.toJson(),
    if (timing != null) 'timing': timing!.json,
    if (palette != null)
      'palette': {
        for (final MapEntry(:key, :value) in palette!.entries) key.json: value,
      },
    if (dark != null) 'dark': dark!,
    if (quietZone != null) 'quiet_zone': quietZone!,
    if (allowInverted != null) 'allow_inverted': allowInverted!,
    if (frame != null) 'frame': frame!.toJson(),
    if (border != null) 'border': border!.toJson(),
    if (shadow != null) 'shadow': shadow!,
    if (colorSpread != null) 'color_spread': colorSpread!.json,
    if (effect != null) 'effect': effect!.toJson(),
    if (textures != null) 'textures': [for (final x in textures!) x.toJson()],
    if (caption != null) 'caption': caption!.toJson(),
    if (seed != null) 'seed': seed!,
    if (logo != null) 'logo': logo!.toJson(),
    if (halftone != null) 'halftone': halftone!.toJson(),
    if (intro != null) 'intro': intro!.toJson(),
    if (idle != null) 'idle': [for (final x in idle!) x.json],
    if (themeTransitionMs != null) 'theme_transition_ms': themeTransitionMs!,
    if (title != null) 'title': title!,
    if (description != null) 'description': description!,
    if (label != null) 'label': label!,
    if (idPrefix != null) 'id_prefix': idPrefix!,
    if (targetSize != null) 'target_size': targetSize!.toJson(),
    if (minify != null) 'minify': minify!,
    if (encoding != null) 'encoding': encoding!.toJson(),
  };
}

